var map=UnityEngine.GameObject.Find("Noryangjin_MapTool").transform;var roads=map.Find("Roads").GetComponentsInChildren<UnityEngine.MeshCollider>(true);var p=new UnityEngine.Vector3(17.43f,.12f,-6.1f);
return string.Join("\n",new[]{UnityEngine.Vector3.zero,UnityEngine.Vector3.right*.12f,UnityEngine.Vector3.left*.12f,UnityEngine.Vector3.forward*.12f,UnityEngine.Vector3.back*.12f}.Select(offset=>offset+" => "+string.Join(",",roads.Where(r=>r.Raycast(new UnityEngine.Ray(p+offset+UnityEngine.Vector3.up*2,UnityEngine.Vector3.down),out _,4)).Select(r=>r.name))))+"\nnear:"+string.Join("\n",roads.OrderBy(r=>(r.bounds.ClosestPoint(p)-p).sqrMagnitude).Take(3).Select(r=>r.name+" "+r.bounds+" "+r.enabled));
